-- ============================================================
-- Sistem Koperasi Simpan Pinjam - PHP Native + MySQL
-- Import lewat phpMyAdmin atau:  mysql -u root -p < database/koperasi_simpan_pinjam.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS koperasi_simpan_pinjam CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE koperasi_simpan_pinjam;

DROP TABLE IF EXISTS angsuran;
DROP TABLE IF EXISTS pinjaman;
DROP TABLE IF EXISTS simpanan;
DROP TABLE IF EXISTS anggota;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS pengaturan;

CREATE TABLE pengaturan (
  id INT PRIMARY KEY,
  nama VARCHAR(120) NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(30),
  simpanan_pokok INT NOT NULL DEFAULT 100000,
  simpanan_wajib INT NOT NULL DEFAULT 50000,
  bunga_default DECIMAL(4,2) NOT NULL DEFAULT 1.50,      -- % per bulan
  provisi_persen DECIMAL(4,2) NOT NULL DEFAULT 1.00,     -- dipotong saat pencairan
  denda_persen_hari DECIMAL(4,2) NOT NULL DEFAULT 0.20,  -- % dari angsuran per hari terlambat
  denda_maks_persen DECIMAL(5,2) NOT NULL DEFAULT 10.00, -- batas maksimal denda per angsuran
  maks_kali_simpanan TINYINT NOT NULL DEFAULT 5          -- plafon pinjaman = n x total simpanan
) ENGINE=InnoDB;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('ketua','bendahara','teller') NOT NULL DEFAULT 'teller'
) ENGINE=InnoDB;

CREATE TABLE anggota (
  id INT AUTO_INCREMENT PRIMARY KEY,
  no_anggota VARCHAR(20) NOT NULL UNIQUE,
  nik CHAR(16) NOT NULL UNIQUE,
  nama VARCHAR(100) NOT NULL,
  jk ENUM('L','P') NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(20),
  pekerjaan VARCHAR(60),
  tgl_gabung DATE NOT NULL,
  status ENUM('aktif','keluar') NOT NULL DEFAULT 'aktif'
) ENGINE=InnoDB;

-- Buku besar simpanan: setiap setoran / penarikan satu baris (saldo = jumlah setor - tarik)
CREATE TABLE simpanan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  anggota_id INT NOT NULL,
  jenis ENUM('pokok','wajib','sukarela') NOT NULL,
  arah ENUM('setor','tarik') NOT NULL DEFAULT 'setor',
  jumlah INT NOT NULL,
  periode CHAR(7) NULL,                -- khusus simpanan wajib: YYYY-MM
  tanggal DATE NOT NULL,
  keterangan VARCHAR(150),
  user_id INT NULL,
  INDEX (anggota_id, jenis), INDEX (tanggal),
  UNIQUE KEY uk_wajib (anggota_id, jenis, periode),
  FOREIGN KEY (anggota_id) REFERENCES anggota(id)
) ENGINE=InnoDB;

CREATE TABLE pinjaman (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  anggota_id INT NOT NULL,
  jumlah INT NOT NULL,
  tenor TINYINT NOT NULL,              -- bulan
  bunga_persen DECIMAL(4,2) NOT NULL,  -- per bulan
  metode ENUM('flat','anuitas') NOT NULL DEFAULT 'flat',
  tujuan VARCHAR(150),
  provisi INT NOT NULL DEFAULT 0,
  diterima INT NOT NULL DEFAULT 0,     -- jumlah bersih yang dicairkan
  status ENUM('diajukan','disetujui','berjalan','lunas','ditolak') NOT NULL DEFAULT 'diajukan',
  tgl_pengajuan DATE NOT NULL,
  tgl_cair DATE NULL,
  catatan VARCHAR(200),
  disetujui_oleh INT NULL,
  INDEX (status),
  FOREIGN KEY (anggota_id) REFERENCES anggota(id)
) ENGINE=InnoDB;

CREATE TABLE angsuran (
  id INT AUTO_INCREMENT PRIMARY KEY,
  pinjaman_id INT NOT NULL,
  ke TINYINT NOT NULL,
  jatuh_tempo DATE NOT NULL,
  pokok INT NOT NULL,
  bunga INT NOT NULL,
  total INT NOT NULL,
  denda INT NOT NULL DEFAULT 0,
  dibayar_at DATE NULL,
  user_id INT NULL,
  UNIQUE KEY uk_ke (pinjaman_id, ke),
  INDEX (jatuh_tempo),
  FOREIGN KEY (pinjaman_id) REFERENCES pinjaman(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Password semua akun: admin123

SET @n := 0;
UPDATE simpanan SET kode = CONCAT(IF(arah='setor','SP','TR'), '-', DATE_FORMAT(tanggal,'%y%m'), '-', LPAD(@n := @n + 1, 5, '0')) ORDER BY tanggal, id;
SET @m := 0;
UPDATE pinjaman SET kode = CONCAT('PJ-', DATE_FORMAT(tgl_pengajuan,'%y%m'), '-', LPAD(@m := @m + 1, 4, '0')) ORDER BY tgl_pengajuan, id;

-- Rapikan data contoh: angsuran selalu dibayar berurutan, jadi tunggakan = angsuran jatuh tempo TERAKHIR yang belum dibayar
CREATE TEMPORARY TABLE tmp_tunggak AS
SELECT a.id,
       (SELECT COUNT(*) FROM angsuran b WHERE b.pinjaman_id = a.pinjaman_id AND b.dibayar_at IS NULL AND b.jatuh_tempo < CURDATE()) u,
       (SELECT COUNT(*) FROM angsuran c WHERE c.pinjaman_id = a.pinjaman_id AND c.jatuh_tempo < CURDATE() AND c.ke > a.ke) sesudah
FROM angsuran a JOIN pinjaman p ON p.id = a.pinjaman_id AND p.status = 'berjalan'
WHERE a.jatuh_tempo < CURDATE();
UPDATE angsuran a JOIN tmp_tunggak t ON t.id = a.id SET a.dibayar_at = NULL, a.denda = 0, a.user_id = NULL WHERE t.sesudah < t.u;
UPDATE angsuran a JOIN tmp_tunggak t ON t.id = a.id SET a.dibayar_at = a.jatuh_tempo - INTERVAL 1 DAY, a.denda = 0, a.user_id = 3 WHERE t.sesudah >= t.u AND a.dibayar_at IS NULL;
-- Pinjaman yang menunggak belum mungkin membayar angsuran berikutnya
UPDATE angsuran a JOIN (SELECT DISTINCT pinjaman_id FROM angsuran WHERE dibayar_at IS NULL AND jatuh_tempo < CURDATE()) x ON x.pinjaman_id = a.pinjaman_id
SET a.dibayar_at = NULL, a.denda = 0, a.user_id = NULL WHERE a.jatuh_tempo >= CURDATE();
DROP TEMPORARY TABLE tmp_tunggak;
